def trend_report(values_by_group):
    """Group records by region and smooth each group's numeric series before averaging."""
    groups = group_by(values_by_group, "region")
    smoothed = []
    for region, records in sorted(groups.items()):
        numeric_series = [r["score"] for r in records]
        smoothed_avg = smooth_series(numeric_series)
        smoothed.append({"region": region, "n": len(records), "total": smoothed_avg})
    return format_table(smoothed, ["region", "n", "total"])

